        unsigned short int rd:1;
        unsigned short int ra:1;
        unsigned short int z:3;
        unsigned short int rcode:4;
    } header;
    unsigned short int qdcount;
    unsigned short int ancount;
    unsigned short int nscount;
    unsigned short int arcount;
    struct question *qd;
    struct resource *an;
    struct resource *ns;
    struct resource *ar;
    unsigned char _packet[MAX_PACKET_LEN];
    unsigned char *_buf;
    unsigned char *_bufEnd;
    unsigned long _len;
    unsigned long _label;
    char *_labels[MAX_NUM_LABELS];
};

#include "1035.c"

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    unsigned char *data = (unsigned char *)malloc(size);
    fread(data, 1, size, f);
    fclose(f);

    struct message m;
    memset(&m, 0, sizeof(struct message));

    unsigned char *dataCopy = (unsigned char *)malloc(size);
    memcpy(dataCopy, data, size);

    printf("sizeof(struct message) = %zu\n", sizeof(struct message));
    printf("sizeof(struct resource) = %zu\n", sizeof(struct resource));
    printf("sizeof(struct question) = %zu\n", sizeof(struct question));
    printf("offsetof _packet = %zu\n", offsetof(struct message, _packet));

    bool success = message_parse(&m, dataCopy, size);

    if (!success) {
        printf("message_parse returned false\n");
        printf("m->_len = %lu\n", m._len);
        free(dataCopy);
        free(data);
        return 0;
    }

    printf("message_parse succeeded\n");
    printf("m->_len = %lu\n", m._len);
    printf("m->ancount = %d\n", m.ancount);

    free(dataCopy);
    free(data);
    return 0;
}
